-- Isolated SQLite prototype only. No production migration; preserve source records.
PRAGMA foreign_keys=ON;
CREATE TABLE canonical_locations(canonical_id TEXT PRIMARY KEY,parent_id TEXT REFERENCES canonical_locations,type TEXT NOT NULL,name_ar TEXT,name_en TEXT,reference_source TEXT,license_status TEXT NOT NULL,verification TEXT NOT NULL);
CREATE TABLE location_aliases(alias TEXT NOT NULL,parent_id TEXT NOT NULL REFERENCES canonical_locations,canonical_id TEXT NOT NULL REFERENCES canonical_locations,source TEXT,PRIMARY KEY(alias,parent_id,canonical_id));
CREATE TABLE business_entities(entity_id TEXT PRIMARY KEY,verification TEXT NOT NULL);
CREATE TABLE business_branches(branch_id TEXT PRIMARY KEY,entity_id TEXT REFERENCES business_entities,location_id TEXT REFERENCES canonical_locations);
CREATE TABLE business_source_records(source_record_id TEXT PRIMARY KEY,entity_id TEXT REFERENCES business_entities,branch_id TEXT REFERENCES business_branches,source_snapshot TEXT NOT NULL,original_payload TEXT NOT NULL);
CREATE TABLE business_categories(category_id TEXT PRIMARY KEY,parent_id TEXT REFERENCES business_categories,label TEXT NOT NULL,reference_system TEXT NOT NULL);
CREATE TABLE category_aliases(alias TEXT NOT NULL,category_id TEXT NOT NULL REFERENCES business_categories,source TEXT,PRIMARY KEY(alias,category_id));
CREATE TABLE business_evidence(evidence_id TEXT PRIMARY KEY,source_record_id TEXT REFERENCES business_source_records,source_url TEXT,source_type TEXT NOT NULL,original_value TEXT,normalized_value TEXT,observed_at TEXT,verification TEXT NOT NULL CHECK(verification IN('VERIFIED','INFERRED','POTENTIAL','UNKNOWN','CONFLICTED')),confidence REAL,calibration_reference TEXT,reason TEXT NOT NULL,CHECK(confidence IS NULL OR calibration_reference IS NOT NULL));
CREATE TABLE business_category_assignments(assignment_id TEXT PRIMARY KEY,source_record_id TEXT NOT NULL REFERENCES business_source_records,category_id TEXT NOT NULL REFERENCES business_categories,evidence_id TEXT NOT NULL REFERENCES business_evidence);
CREATE TABLE product_service_taxonomy(product_id TEXT PRIMARY KEY,parent_id TEXT REFERENCES product_service_taxonomy,source_system TEXT NOT NULL,source_version TEXT NOT NULL,original_id TEXT NOT NULL,label TEXT,UNIQUE(source_system,source_version,original_id));
CREATE TABLE business_product_roles(role_id TEXT PRIMARY KEY,source_record_id TEXT NOT NULL REFERENCES business_source_records,product_id TEXT NOT NULL REFERENCES product_service_taxonomy,role TEXT NOT NULL CHECK(role IN('SELLER','BUYER','BOTH','POTENTIAL_BUYER','UNKNOWN')),sale_evidence_id TEXT REFERENCES business_evidence,purchase_evidence_id TEXT REFERENCES business_evidence,decision TEXT NOT NULL,CHECK(role!='SELLER' OR sale_evidence_id IS NOT NULL),CHECK(role!='BUYER' OR purchase_evidence_id IS NOT NULL),CHECK(role!='BOTH' OR (sale_evidence_id IS NOT NULL AND purchase_evidence_id IS NOT NULL)));
CREATE TABLE normalization_review_queue(review_id TEXT PRIMARY KEY,source_record_id TEXT REFERENCES business_source_records,issue TEXT NOT NULL,proposed_value TEXT,reviewer_id TEXT,status TEXT NOT NULL DEFAULT 'PENDING');
